section.programlisting:
public sealed class RexxCommandContext            // ooRexx's .CommandContext
{
    public RexxInterpreter Interpreter { get; }        // to call Rexx code
    public RexxObject Context { get; }                 // the .CommandContext itself
    public string Environment { get; }
    public RexxObject? Pending { get; }
    public bool IsValid { get; }
    public bool IsRedirected(string kind);             // "Input", "Output", "Error", "Same"
    public RexxObject Input { get; }                   // a .CommandInput (WITH INPUT)
    public RexxObject Output { get; }                  // a .CommandOutput (WITH OUTPUT)
    public RexxObject Error { get; }                   // a .CommandOutput (WITH ERROR)
    public object? this[string name] { get; set; }     // the caller's variable ("X", "STEM.1")
    public object? GetVar(string name);
    public void SetVar(string name, object? value);
    public bool HasVar(string name);
    public void DropVar(string name);
    public RexxObject Variables { get; }
    public object? Raise(string condition, object? rc [, object? description [, object? additional]]);
    public object? RaiseError(object? rc);
    public object? RaiseFailure(object? rc);
}

example.programlisting:
using System;
using Rexx.Net;

using var rexx = RexxInterpreter.Create();
rexx.AddCommandEnvironment("APP", (command, caller) =>
{
    switch (command.Split(' ')[0].ToUpperInvariant())
    {
        case "UPPER": return command.Substring(6).ToUpperInvariant();
        case "SETX": caller["X"] = 42; return 0;
        case "LINES":
            int count = 0;
            for (; caller.Input.Send("LINES")!.ToString() != "0"; count++)
                caller.Output.Send("LINEOUT", $"{count + 1}: {caller.Input.Send("LINEIN")}");
            return count;
        default: return caller.Raise("ERROR", 10, command, "unknown command: " + command);
    }
});
Console.WriteLine(rexx.Run<string>("address app 'upper hello'; return rc"));
Console.WriteLine(rexx.Run<string>("address app 'setx'; return x rc"));
Console.WriteLine(rexx.Run<string>(
    "in = .array~of('a', 'b'); out = .array~new\n" +
    "address app 'lines' with input using (in) output using (out)\n" +
    "return rc out~makeString('L', ' / ')"));
Console.WriteLine(rexx.Run<string>("signal on error; address app 'nope'; return 'no'\n" +
                                   "error: return 'ERROR' rc condition('A')"));

using System;
using System.IO;
using Rexx.Net;

using var rexx = RexxInterpreter.Create();
rexx.Run("say 'one'; say 'two' || '0a'x || 'lines'");
rexx.StreamPrefixes = false;
rexx.Run("say 'plain'");
var output = new StringWriter();
rexx.Output = output;
rexx.Input = new StringReader("Ann\n");
rexx.Run("say 'Name?'; pull name; say 'Hello,' name");
rexx.Output = null; rexx.Input = null;
Console.Write(output.ToString());

section.programlisting:
public abstract class RexxCallContext
{
    public RexxInterpreter Interpreter { get; }
    public object? this[string name] { get; set; }     // the caller's variable ("X", "STEM.1")
    public bool HasVariable(string name);
    public void Drop(string name);
    public IReadOnlyDictionary<string, object?> Variables { get; }   // a copy
}
public sealed class RexxFunctionCall : RexxCallContext
{
    public string Name { get; }                        // uppercased, unless called as a literal
    public IReadOnlyList<object?> Arguments { get; }   // RexxString, RexxObject, a .NET object, null, RexxValue.Omitted
    public bool IsSubroutine { get; }                  // CALL name
    public T Arg<T>(int i, T fallback = default!);     // from 0, by Rexx's rules
}

example.programlisting:
using System;
using System.Collections.Generic;
using Rexx.Net;

using var rexx = RexxInterpreter.Create();
rexx.AddFunction("hypot", (double a, double b) => Math.Sqrt(a * a + b * b));
rexx.AddFunction("greet", (string who, string greeting = "Hello") => $"{greeting}, {who}!");
rexx.AddFunction("vars", call => $"{call.Name} sees x = {call["X"]}");
var settings = new Dictionary<string, object?> { ["COLOR"] = "blue" };
rexx.AddValueSelector("APP", name => settings.GetValueOrDefault(name.ToUpperInvariant()),
                             (name, value) => settings[name.ToUpperInvariant()] = value);

Console.WriteLine(rexx.Run("return hypot(3, 4)"));
Console.WriteLine(rexx.Run("return greet('Ann') greet('Bob', 'Hola')"));
Console.WriteLine(rexx.Run("x = 42; return vars()"));
Console.WriteLine(rexx.Run("old = value('color', 'red', 'APP'); return old value('color', , 'APP')"));
Console.WriteLine(rexx.Run("signal on syntax; return hypot(1)\n" +
                           "syntax: return condition('O')~code"));

using System;
using System.Threading;
using Rexx.Net;

using var rexx = RexxInterpreter.Create();
using var cts = new CancellationTokenSource(200);
try { rexx.Run("do forever; nop; end", cts.Token); }
catch (OperationCanceledException e) { Console.WriteLine($"cancelled: {(e.InnerException as RexxException)?.Code}"); }
Console.WriteLine(rexx.Run<string>("return 'still usable'"));
